
//! Actual conditional host, same-owner public report, and productive no-model IO.
use super::*;
use crate::{policy_request::{AnalysisContext,PolicyInputRequest,WorkspacePolicyRequest,WorkspaceAuxiliaryQuestion as Q},request::{BuildOutcome,BuildRequest,Command},input_snapshot::{RecordingInputs,SnapshotProvider,FileSystemInputs,Stamp,FolderListing,CapturedInputRead,PolicyDirectoryListing}};
use std::{io,path::Path,collections::BTreeSet,sync::Mutex};
#[path="../../../../analyze/fixtures/native-engine-layering-workspace/fixture.rs"]mod fixture;
#[path="../../../../analyze/fixtures/report_configuration.rs"]mod complete_report_configuration;
fn request(case:&str)->(crate::runner_host::BuildHost,BuildRequest,PathBuf){let root=crate::test_scratch::dir(&format!("engine-conditional-{case}"));for(relative,text)in fixture::files(case){let p=root.join(relative);std::fs::create_dir_all(p.parent().unwrap()).unwrap();std::fs::write(p,text).unwrap();}let cfg=root.join("tools/ci/lint_scopes.toml");std::fs::create_dir_all(cfg.parent().unwrap()).unwrap();if !cfg.exists(){std::fs::write(&cfg,"").unwrap();}complete_report_configuration::complete(&cfg);let Command::Build(request)=crate::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()]).unwrap()else{panic!("actual PrepareQuery")};let mut request=*request;request.no_cache=true;request.exact_inputs=true;request.progress_enabled=false;request.workers=1;request.cache_root=Some(root.join("cache"));let mut intent=PolicyInputRequest::default();intent.analysis_context=Some(AnalysisContext::OriginalAnalyze0290);intent.workspace=Some(WorkspacePolicyRequest{root:root.clone(),recursive_roots:vec![root.join("code")],configuration:cfg});intent.workspace_auxiliary=vec![Q::EngineLayering];request.policy_inputs=Some(intent);(crate::runner_host::BuildHost::default(),request,root)}
fn query(request:&BuildRequest,pins:(u128,u128,u128))->crate::daemon::query::QueryRequest{let w=request.policy_inputs.as_ref().unwrap().workspace.as_ref().unwrap();crate::daemon::query::QueryRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),timeout_seconds:None,project:request.project.clone(),defines:Default::default(),engine_template:None,bootstrap_catalog:false,expected_revision:Some(format!("{:032x}",pins.0)),expected_source_revision:Some(format!("{:032x}",pins.1)),expected_policy_revision:Some(format!("{:032x}",pins.2)),queries:vec![],source_queries:vec![crate::daemon::query::SourceQuery::NativeWorkspaceSemanticReportPage{root:w.root.clone(),configuration:w.configuration.clone(),lints:vec!["engine_layering".into()],cursor:None,limit:1}]}}
#[test]fn actual_engine_exempt_selection_finishes_before_bad_missing_and_nonfile_manifest_without_semantic_tree(){for manifest in 0..3{let(mut host,request,root)=request("exempt");match manifest{0=>std::fs::write(root.join("deepquarry.dme"),"#include \"missing_native_dependency.dm\"\n").unwrap(),1=>std::fs::remove_file(root.join("deepquarry.dme")).unwrap(),_=>{std::fs::remove_file(root.join("deepquarry.dme")).unwrap();std::fs::create_dir(root.join("deepquarry.dme")).unwrap();}}let db=Arc::clone(host.query_db());let before=db.db().stats(dm_query::Kind(4)).computed;let outcome=crate::request_runner::run_build_with_host(request.clone(),&mut host).unwrap();assert!(matches!(outcome,BuildOutcome::RawQueryPrepared{..}));assert!(host.query_tree().is_none());let state=host.query_state();let state=state.lock().unwrap();assert!(state.snapshot.is_none());let raw=state.raw_snapshot.as_ref().unwrap();assert!(raw.capture.engine_no_model().is_ok());assert_eq!(raw.capture.raw_input_files().count(),0,"metadata-only branch must not acquire even unrelated CODE payload");assert!(!raw.capture.covers_code_dm(&mut |_|Ok(())).unwrap(),"metadata role cannot certify generic CODE payload");let query=query(&request,(raw.revision(),raw.source_revision(),raw.policy_revision()));let reply=crate::daemon::query::evaluate_raw_snapshot(&query,raw,&state).unwrap();crate::daemon::query::validate_effect_batch_for_test(&query,&reply).unwrap();let value:serde_json::Value=serde_json::from_str(reply.jsonl.trim()).unwrap();assert_eq!(value["row"],"source_native_workspace_semantic_report");assert_eq!(value["lint_whitelist"],serde_json::json!(["engine_layering"]));assert_eq!(value["total_items"],0);assert_eq!(db.db().stats(dm_query::Kind(4)).computed,before);let mut wrong=query.clone();wrong.expected_source_revision=Some("0".repeat(32));assert!(crate::daemon::query::evaluate_raw_snapshot(&wrong,raw,&state).is_err());wrong=query;wrong.source_queries=vec![crate::daemon::query::SourceQuery::NativeWorkspaceRawTreeReportPage{root:root.clone(),configuration:root.join("tools/ci/lint_scopes.toml"),lints:vec!["ownership".into()],cursor:None,limit:1}];assert!(crate::daemon::query::evaluate_raw_snapshot(&wrong,raw,&state).is_err());}}
struct Denied{payloads:BTreeSet<PathBuf>,reads:Mutex<Vec<PathBuf>>}
impl Denied{fn observe(&self,p:&Path)->io::Result<()>{self.reads.lock().unwrap().push(p.to_owned());if self.payloads.contains(p){Err(io::Error::from_raw_os_error(1450))}else{Ok(())}}}
impl SnapshotProvider for Denied{fn stamp(&self,p:&Path)->io::Result<Stamp>{self.observe(p)?;FileSystemInputs.stamp(p)}fn read(&self,p:&Path)->io::Result<(Stamp,Vec<u8>)>{self.observe(p)?;FileSystemInputs.read(p)}fn list(&self,p:&Path)->io::Result<FolderListing>{FileSystemInputs.list(p)}fn read_policy_bounded(&self,p:&Path,n:usize)->io::Result<Option<CapturedInputRead>>{self.observe(p)?;FileSystemInputs.read_policy_bounded(p,n)}fn policy_directory(&self,p:&Path,follow:bool,n:usize)->io::Result<Option<PolicyDirectoryListing>>{FileSystemInputs.policy_directory(p,follow,n)}}
#[test]fn actual_engine_metadata_preflight_reads_no_dme_or_dm_payload_and_rejects_foreign_recording_or_selected_no_model(){let(_,request,root)=request("global");let intent=request.policy_inputs.unwrap().admit().unwrap();let denied=Denied{payloads:BTreeSet::from([root.join("deepquarry.dme"),root.join("code/engine/probe.dm"),root.join("code/library/arbitrary.dm")]),reads:Mutex::new(vec![])};let inputs=RecordingInputs::new(&denied,0).with_initial_environment(dm_preprocess::InitialEnvironment::OriginalChecker0290);let selected=crate::runner_host::workspace_discovery::discover_engine_preflight(&inputs,&intent).unwrap();assert!(!selected.is_empty());assert!(selected.into_unselected().is_err());for p in &denied.payloads{assert!(!denied.reads.lock().unwrap().contains(p),"metadata selection opened payload {p:?}");}let proof=crate::runner_host::workspace_discovery::discover_engine_preflight(&inputs,&intent).unwrap();let foreign=RecordingInputs::new(&denied,0).with_initial_environment(dm_preprocess::InitialEnvironment::OriginalChecker0290);assert!(proof.require(&foreign).is_err());let config=root.join("tools/ci/lint_scopes.toml");let failed=Denied{payloads:BTreeSet::from([config]),reads:Mutex::new(vec![])};let inputs=RecordingInputs::new(&failed,0).with_initial_environment(dm_preprocess::InitialEnvironment::OriginalChecker0290);assert_eq!(crate::runner_host::workspace_discovery::discover_engine_preflight(&inputs,&intent).err().unwrap().raw_os_error(),Some(1450));}
#[test]fn actual_engine_selected_whole_public_reports_match_same_complete_producer_and_hard_messages_without_source_text(){for case in fixture::CASES{if *case=="exempt"{continue}let(mut host,request,root)=request(case);let outcome=crate::request_runner::run_build_with_host(request.clone(),&mut host).unwrap();assert!(matches!(outcome,BuildOutcome::QueryPrepared{..}));let state=host.query_state();let state=state.lock().unwrap();assert!(state.raw_snapshot.is_none());let snapshot=state.snapshot.as_ref().unwrap();let expected=snapshot.with_original_engine_layering_policy(|data,_,_|Ok(data.sites().iter().map(|site|serde_json::to_value(site).unwrap()).collect::<Vec<_>>())).unwrap();let mut q=query(&request,(snapshot.tree.identity(),snapshot.source_revision,snapshot.policy_revision.unwrap()));let mut sites=vec![];loop{let reply=crate::daemon::query::evaluate_snapshot(&q,&snapshot.tree,&state).unwrap();crate::daemon::query::validate_effect_batch_for_test(&q,&reply).unwrap();let row:serde_json::Value=serde_json::from_str(reply.jsonl.trim()).unwrap();assert_eq!(row["row"],"source_native_workspace_semantic_report");assert_eq!(row["lint_whitelist"],serde_json::json!(["engine_layering"]));assert_eq!(row["full_policy_parity"],false);for item in row["items"].as_array().unwrap(){assert_eq!(item["kind"],"hard_site");assert!(item.get("source_text").is_none());sites.push(item["site"].clone());}if row["next_cursor"].is_null(){break}if let crate::daemon::query::SourceQuery::NativeWorkspaceSemanticReportPage{cursor,..}=&mut q.source_queries[0]{*cursor=Some(serde_json::from_value(row["next_cursor"].clone()).unwrap());}}assert_eq!(sites,expected,"actual public complete result {case}");if *case=="global"{assert!(sites.iter().any(|site|site["msg"].as_str().unwrap().contains("ordinary_helper")));}let _=root;}}

#[test]fn actual_engine_configuration_edit_switches_conditional_roles_without_reusing_stale_clean_frame(){let(mut host,request,root)=request("exempt");let db=Arc::clone(host.query_db());let first=crate::request_runner::run_build_with_host(request.clone(),&mut host).unwrap();assert!(matches!(first,BuildOutcome::RawQueryPrepared{..}));let old_query={let state=host.query_state();let state=state.lock().unwrap();let raw=state.raw_snapshot.as_ref().unwrap();query(&request,(raw.revision(),raw.source_revision(),raw.policy_revision()))};std::fs::write(root.join("tools/ci/lint_scopes.toml"),"").unwrap();let second=crate::request_runner::run_build_with_host(request.clone(),&mut host).unwrap();assert!(matches!(second,BuildOutcome::QueryPrepared{..}));assert!(Arc::ptr_eq(&db,host.query_db()));{let state=host.query_state();let state=state.lock().unwrap();assert!(state.raw_snapshot.is_none());let snapshot=state.snapshot.as_ref().unwrap();assert!(crate::daemon::query::evaluate_snapshot(&old_query,&snapshot.tree,&state).is_err(),"old metadata-only clean reply cannot survive new selected source/config");snapshot.with_original_engine_layering_policy(|data,_,_|{assert!(data.sites().iter().any(|site|site.msg.contains("ordinary_helper")));Ok(())}).unwrap();}std::fs::write(root.join("tools/ci/lint_scopes.toml"),"[lint.engine_layering]\nexempt_files=[\"code/engine/probe.dm\"]\n").unwrap();let before=db.db().stats(dm_query::Kind(4)).computed;let third=crate::request_runner::run_build_with_host(request.clone(),&mut host).unwrap();assert!(matches!(third,BuildOutcome::RawQueryPrepared{..}));assert!(host.query_tree().is_none());let state=host.query_state();let state=state.lock().unwrap();let raw=state.raw_snapshot.as_ref().unwrap();assert!(state.snapshot.is_none());assert_eq!(raw.capture.raw_input_files().count(),0);assert_eq!(db.db().stats(dm_query::Kind(4)).computed,before,"returning to no-selected must not request semantic bodies");}
